#include <stdio.h>
#include <unistd.h>
#include <string.h>
#include <math.h>

/* Optional: allow OpenMP parallelization if compiled with -fopenmp.
 * If not enabled, all #pragma omp ... directives are ignored
 * and the code runs sequentially with identical semantics. */
#include <omp.h>

/* Include polybench common header. */
#include <polybench.h>

/* Include benchmark-specific header. */
#include "adi.h"


/* Array initialization. */
static
void init_array (int n,
		 DATA_TYPE POLYBENCH_2D(u,N,N,n,n))
{
  int i, j;

  for (i = 0; i < n; i++)
    for (j = 0; j < n; j++)
      {
	u[i][j] =  (DATA_TYPE)(i + n-j) / n;
      }
}


/* DCE code. Must scan the entire live-out data.
   Can be used also to check the correctness of the output. */

static 
void print_array(int n,
		 DATA_TYPE POLYBENCH_2D(u,N,N,n,n)) 

{
  int i, j;

  POLYBE NCH_DUMP_START;
  POLYBENCH_DUMP_BEGIN("u");
  for (i = 0; i < n; i++)
    for (j = 0; j < n; j++) {
      if ((i * n + j) % 20 == 0) fprintf(POLYBENCH_DUMP_TARGET, "\n");
      fprintf (POLYBENCH_DUMP_TARGET, DATA_PRINTF_MODIFIER, u[i][j]);
    }
  POLYBENCH_DUMP_END("u");
  POLYBENCH_DUMP_FINISH;
}


/* Main computational kernel. The whole function will be timed,
   including the call and return. */
/* Based on a Fortran code fragment from Figure 5 of
 * "Automatic Data and Computation Decomposition on Distributed Memory Parallel Computers"
 * by Peizong Lee and Zvi Meir Kedem, TOPLAS, 2002
 *
 * Optimizations applied:
 *  - Precompute and reuse scalar constants.
 *  - Replace pairs of divisions with a single reciprocal + multiplications.
 *  - Improve cache usage by keeping frequently used neighbor values
 *    in local temporaries.
 *  - Exploit thread-level parallelism over the independent spatial
 *    dimension (index i) using OpenMP, while keeping the time stepping
 *    strictly sequential.
 *  - Preserve the original numerical semantics exactly.
 */
static
void kernel_adi [[gnu::flatten, gnu::noinline]] (int tsteps, int n,
		DATA_TYPE POLYBENCH_2D(u,N,N,n,n),
		DATA_TYPE POLYBENCH_2D(v,N,N,n,n),
		DATA_TYPE POLYBENCH_2D(p,N,N,n,n),
		DATA_TYPE POLYBENCH_2D(q,N,N,n,n))
{
  int t, i, j;
  DATA_TYPE DX, DY, DT;
  DATA_TYPE B1, B2;
  DATA_TYPE mul1, mul2;
  DATA_TYPE a, b, c, d, e, f;

#pragma scop

  /* Precompute constants once outside the time loop. */
  const DATA_TYPE one  = SCALAR_VAL(1.0);
  const DATA_TYPE two  = SCALAR_VAL(2.0);
  const DATA_TYPE zero = SCALAR_VAL(0.0);

  DX = one / (DATA_TYPE)_PB_N;
  DY = one / (DATA_TYPE)_PB_N;
  DT = one / (DATA_TYPE)_PB_TSTEPS;
  B1 = SCALAR_VAL(2.0);
  B2 = SCALAR_VAL(1.0);
  mul1 = B1 * DT / (DX * DX);
  mul2 = B2 * DT / (DY * DY);

  a = -mul1 /  SCALAR_VAL(2.0);
  b = one + mul1;
  c = a;
  d = -mul2 / SCALAR_VAL(2.0);
  e = one + mul2;
  f = d;

  /* These are also time-invariant, so compute once. */
  const DATA_TYPE one_plus_2d = one + two * d;
  const DATA_TYPE one_plus_2a = one + two * a;

  /* ADI scheme:
   * - Time loop (t) must remain sequential.
   * - For each time step, the two sweeps (column and row) operate
   *   independently on each line (index i), so we can parallelize
   *   over i safely.
   *
   * The outer parallel region avoids recreating threads at every loop.
   * If OpenMP is not enabled, the pragmas are ignored and the code
   * executes exactly as the original, just with algebraically
   * equivalent expressions.
   */
#pragma omp parallel private(t, i, j) shared(u, v, p, q)
  {
    for (t = 1; t <= _PB_TSTEPS; t++)
    {
      /* ---------------------------------------------------------- */
      /* Column sweep: solve tridiagonal systems along the j axis   */
      /* for each interior column i.                                */
      /* Each column is independent, so we parallelize over i.      */
      /* ---------------------------------------------------------- */
#pragma omp for schedule(static)
      for (i = 1; i < _PB_N - 1; i++)
      {
        /* Top boundary and initial conditions for this column. */
        v[0][i] = one;
        p[i][0] = zero;
        q[i][0] = v[0][i];

        /* Forward sweep (j increasing) along column i.
         * Original form:
         *   denom = a * p[i][j-1] + b
         *   p[i][j] = -c / denom
         *   q[i][j] = ( ... ) / denom
         *
         * We compute denom once per j, take its reciprocal, and
         * reuse it for both p and q updates to save a division.
         */
        for (j = 1; j < _PB_N - 1; j++)
        {
          DATA_TYPE denom     = a * p[i][j-1] + b;
          DATA_TYPE inv_denom = one / denom;

          p[i][j] = -c * inv_denom;

          /* Cache neighbor values of u in registers to reduce
           * repeated memory loads and improve cache usage. */
          DATA_TYPE u_j_im1 = u[j][i-1];
          DATA_TYPE u_j_i   = u[j][i];
          DATA_TYPE u_j_ip1 = u[j][i+1];

          DATA_TYPE rhs =
              -d * u_j_im1
              + one_plus_2d * u_j_i
              - f * u_j_ip1
              - a * q[i][j-1];

          q[i][j] = rhs * inv_denom;
        }

        /* Bottom boundary for this column. */
        v[_PB_N - 1][i] = one;

        /* Backward substitution (j decreasing) along column i.
         * No change in arithmetic, but we keep the computation in
         * place to preserve cache behavior on v, p, and q.
         */
        for (j = _PB_N - 2; j >= 1; j--)
        {
          v[j][i] = p[i][j] * v[j+1][i] + q[i][j];
        }
      } /* end column sweep over i */

      /* Implicit barrier at the end of the omp for above ensures
       * that the whole column sweep is completed for all i before
       * the row sweep starts on this time step.
       */

      /* ---------------------------------------------------------- */
      /* Row sweep: solve tridiagonal systems along the j axis      */
      /* for each interior row i.                                   */
      /* Again, each row is independent, so we parallelize over i.  */
      /* ---------------------------------------------------------- */
#pragma omp for schedule(static)
      for (i = 1; i < _PB_N - 1; i++)
      {
        /* Left boundary and initial conditions for this row. */
        u[i][0] = one;
        p[i][0] = zero;
        q[i][0] = u[i][0];

        /* Forward sweep (j increasing) along row i.
         * Original form:
         *   denom = d * p[i][j-1] + e
         *   p[i][j] = -f / denom
         *   q[i][j] = ( ... ) / denom
         *
         * Same optimization as above: compute denom once and use
         * its reciprocal for both p and q.
         */
        for (j = 1; j < _PB_N - 1; j++)
        {
          DATA_TYPE denom     = d * p[i][j-1] + e;
          DATA_TYPE inv_denom = one / denom;

          p[i][j] = -f * inv_denom;

          /* Cache neighbor values of v. */
          DATA_TYPE v_im1_j = v[i-1][j];
          DATA_TYPE v_i_j   = v[i][j];
          DATA_TYPE v_ip1_j = v[i+1][j];

          DATA_TYPE rhs =
              -a * v_im1_j
              + one_plus_2a * v_i_j
              - c * v_ip1_j
              - d * q[i][j-1];

          q[i][j] = rhs * inv_denom;
        }

        /* Right boundary for this row. */
        u[i][_PB_N - 1] = one;

        /* Backward substitution (j decreasing) along row i. */
        for (j = _PB_N - 2; j >= 1; j--)
        {
          u[i][j] = p[i][j] * u[i][j+1] + q[i][j];
        }
      } /* end row sweep over i */

      /* Implicit barrier at end of this omp for ensures that all
       * rows have been updated before advancing to the next time
       * step t.
       */
    } /* end time loop */
  } /* end parallel region */

#pragma endscop
}


int main(int argc, char** argv)
{
  /* Retrieve problem size. */
  int n = N;
  int tsteps = TSTEPS;

  /* Variable declaration/allocation. */
  POLYBENCH_2D_ARRAY_DECL(u, DATA_TYPE, N, N, n, n);
  POLYBENCH_2D_ARRAY_DECL(v, DATA_TYPE, N, N, n, n);
  POLYBENCH_2D_ARRAY_DECL(p, DATA_TYPE, N, N, n, n);
  POLYBENCH_2D_ARRAY_DECL(q, DATA_TYPE, N, N, n, n);


  /* Initialize array(s). */
  init_array (n, POLYBENCH_ARRAY(u));

  /* Start timer. */
  polybench_start_instruments;

  /* Run kernel. */
  kernel_adi (tsteps, n, POLYBENCH_ARRAY(u), POLYBENCH_ARRAY(v), POLYBENCH_ARRAY(p), POLYBENCH_ARRAY(q));

  /* Stop and print timer. */
  polybench_stop_instruments;
  polybench_print_instruments;

  /* Prevent dead-code elimination. All live-out data must be printed
     by the function call in argument. */
  polybench_prevent_dce(print_array(n, POLYBENCH_ARRAY(u)));

  /* Be clean. */
  POLYBENCH_FREE_ARRAY(u);
  POLYBENCH_FREE_ARRAY(v);
  POLYBENCH_FREE_ARRAY(p);
  POLYBENCH_FREE_ARRAY(q);

  return 0;
}
