        /* Using 'denom' once for both p and q is semantically
           equivalent to recomputing (a*p[i][j-1] + b) twice, because
           the expression is free of side effects and its operands do
           not change within the iteration. */
        p_i[j] = -c / denom;

        q_i[j] =
          (-d * u_[j][i-1] +
           one_plus_2d * u_[j][i] -
           f * u_[j][i+1] -
           a * q_i[j-1]) / denom;
      }

      v_[nPB-1][i] = one;

      /* Backward substitution in j-direction. */
      for (j = nPB - 2; j >= 1; --j) {
        v_[j][i] = p_i[j] * v_[j+1][i] + q_i[j];
      }
    }

    /* ----------------------------------------------------------------
     * Row sweep
     * ----------------------------------------------------------------
     * Symmetric to the column sweep, but now each iteration in i
     * processes a tridiagonal solve along the j dimension for u.
     * We again:
     *  - use row pointers for p, q and u,
     *  - hoist the denominator d*p[i][j-1] + e.
     */
    for (i = 1; i < nPB - 1; ++i) {
      DATA_TYPE *restrict p_i = p_[i];
      DATA_TYPE *restrict q_i = q_[i];
      DATA_TYPE *restrict u_i = u_[i];

      /* Boundary conditions for this row. */
      u_i[0] = one;
      p_i[0] = SCALAR_VAL(0.0);
      /* q_i[0] = u[i][0];  u[i][0] has just been set to 1.0. */
      q_i[0] = one;

      /* Forward sweep in j-direction. */
      for (j = 1; j < nPB - 1; ++j) {
        const DATA_TYPE denom = d * p_i[j-1] + e;

        p_i[j] = -f / denom;

        q_i[j] =
          (-a * v_[i-1][j] +
           one_plus_2a * v_[i][j] -
           c * v_[i+1][j] -
           d * q_i[j-1]) / denom;
      }

      u_i[nPB-1] = one;

      /* Backward substitution in j-direction. */
      for (j = nPB - 2; j >= 1; --j) {
        u_i[j] = p_i[j] * u_i[j+1] + q_i[j];
      }
    }
  }
#pragma endscop
}


int main(int argc, char** argv)
{
