/* Based on a Fortran code fragment from Figure 5 of
 * "Automatic Data and Computation Decomposition on Distributed Memory Parallel Computers"
 * by Peizong Lee and Zvi Meir Kedem, TOPLAS, 2002
 */
static
void kernel_adi [[gnu::flatten, gnu::noinline]] (int tsteps, int n,
		DATA_TYPE POLYBENCH_2D(u,N,N,n,n),
		DATA_TYPE POLYBENCH_2D(v,N,N,n,n),
		DATA_TYPE POLYBENCH_2D(p,N,N,n,n),
		DATA_TYPE POLYBENCH_2D(q,N,N,n,n))
{
  int t, i, j;
  DATA_TYPE DX, DY, DT;
  DATA_TYPE B1, B2;
  DATA_TYPE mul1, mul2;
  DATA_TYPE a, b, c, d, e, f;

#pragma scop

  /* Precompute scalar coefficients outside the time loop. */
  const DATA_TYPE one  = SCALAR_VAL(1.0);
  const DATA_TYPE zero = SCALAR_VAL(0.0);
  const DATA_TYPE two  = SCALAR_VAL(2.0);

  DX = one / (DATA_TYPE)_PB_N;
  DY = one / (DATA_TYPE)_PB_N;
  DT = one / (DATA_TYPE)_PB_TSTEPS;
  B1 = SCALAR_VAL(2.0);
  B2 = SCALAR_VAL(1.0);
  mul1 = B1 * DT / (DX * DX);
  mul2 = B2 * DT / (DY * DY);

  a = -mul1 / two;
  b = one + mul1;
  c = a;
  d = -mul2 / two;
  e = one + mul2;
  f = d;

  /* Constants used repeatedly inside the loops; computing them once here
     is exactly equivalent to recomputing them every iteration but cheaper. */
  const DATA_TYPE one_plus_2d = one + two * d;
  const DATA_TYPE one_plus_2a = one + two * a;

  for (t = 1; t <= _PB_TSTEPS; t++) {
    /* Column Sweep: solve tridiagonal systems along columns.
       Each iteration over i (a column index) is independent, so we
       parallelize over i. Dependencies along j are preserved. */

#pragma omp parallel for schedule(static) private(j)
    for (i = 1; i < _PB_N - 1; i++) {
      /* Row pointers improve locality for p, q, u, u is accessed transposed here. */
      DATA_TYPE *p_row = p[i];
      DATA_TYPE *q_row = q[i];

      v[0][i] = one;
      p_row[0] = zero;
      q_row[0] = one;

      /* Forward sweep (Thomas algorithm) along j. */
      for (j = 1; j < _PB_N - 1; j++) {
        /* Load values once into temporaries to reduce memory traffic. */
        const DATA_TYPE u_j_im1 = u[j][i-1];
        const DATA_TYPE u_j_i   = u[j][i];
        const DATA_TYPE u_j_ip1 = u[j][i+1];

        const DATA_TYPE p_prev = p_row[j-1];
        const DATA_TYPE q_prev = q_row[j-1];

        /* Common subexpression elimination for the denominator.
           This is mathematically identical to recomputing it twice. */
        const DATA_TYPE denom = a * p_prev + b;

        p_row[j] = -c / denom;
        q_row[j] = (-d * u_j_im1 +
                    one_plus_2d * u_j_i -
                    f * u_j_ip1 -
                    a * q_prev) / denom;
      }

      v[_PB_N-1][i] = one;

      /* Backward sweep along j. Dependency is along j only, so order is unchanged. */
      for (j = _PB_N - 2; j >= 1; j--) {
        v[j][i] = p_row[j] * v[j+1][i] + q_row[j];
      }
    }

    /* Row Sweep: solve tridiagonal systems along rows.
       Again, iterations over i (row index) are independent. */

#pragma omp parallel for schedule(static) private(j)
    for (i = 1; i < _PB_N - 1; i++) {
      DATA_TYPE *u_row = u[i];
      DATA_TYPE *p_row = p[i];
      DATA_TYPE *q_row = q[i];

      u_row[0] = one;
      p_row[0] = zero;
      q_row[0] = one;

      /* Forward sweep along j. */
      for (j = 1; j < _PB_N - 1; j++) {
        const DATA_TYPE p_prev = p_row[j-1];
        const DATA_TYPE q_prev = q_row[j-1];

        const DATA_TYPE denom = d * p_prev + e;

        p_row[j] = -f / denom;
        q_row[j] = (-a * v[i-1][j] +
                    one_plus_2a * v[i][j] -
                    c * v[i+1][j] -
                    d * q_prev) / denom;
      }

      u_row[_PB_N-1] = one;

      /* Backward sweep along j. */
      for (j = _PB_N - 2; j >= 1; j--) {
        u_row[j] = p_row[j] * u_row[j+1] + q_row[j];
      }
    }
  }
#pragma endscop
}


